// Two parallel extracts feed into this node. Read each explicitly by name
// so we always know which set of rows we're looking at, then join by Tally Code.
//
// From RM sheet we need:      Tally Code, Location, Lead Time (Days), Lead Time Consumption
// From RM Receipt we need:    Tally Code, RM Code (ERP Code), Location, RM Specification,
//                             Grade, Component Item (Component Name), Group, Section
//
// The RM Receipt sheet is preferred for the static/metadata fields (Location, RM
// Specification, Grade, Component Item, Group, Section, ERP Code) because it holds
// the up-to-date master values. The RM sheet is used for Lead Time and Lead Time
// Consumption (which only exist there).

const rmItems      = $('Extract RM Sheet').all().map(i => i.json || {});
const receiptItems = $('Extract RM Receipt Sheet').all().map(i => i.json || {});

// Index RM sheet by Tally Code.
const rmByTally = new Map();
for (const r of rmItems) {
  const key = r['Tally Code'];
  if (key !== undefined && key !== null && key !== '') rmByTally.set(String(key).trim(), r);
}

const out = [];
for (const rcpt of receiptItems) {
  const tally = rcpt['Tally Code'];
  if (tally === undefined || tally === null || tally === '') continue;
  const rm = rmByTally.get(String(tally).trim()) || {};

  const row = {
    'Tally Code':             tally,
    'RM Code':                rcpt['ERP Code'] ?? rcpt['RM Code'] ?? '',
    'Location':               rcpt['Location'] ?? rm['Location'] ?? '',
    'RM Specification':       rcpt['RM Specification'] ?? rm['RM Specification'] ?? '',
    'Grade':                  rcpt['Grade'] ?? rm['Grade'] ?? '',
    'Component Item':         rcpt['Component Name'] ?? rcpt['Component Item'] ?? rm['Component Item'] ?? '',
    'Group':                  rcpt['Group'] ?? '',
    'Section':                rcpt['Section'] ?? '',
    'Lead Time (Days)':       rm['Lead Time (Days)'] ?? '',
    'Lead Time Consumption':  rm['Lead Time Consumption'] ?? ''
  };
  out.push(row);
}

if (out.length === 0) {
  throw new Error('No rows produced from RM Green Level. Check that both "RM" (headers at row 4) and "RM Receipt" (headers at row 1) sheets exist and have data.');
}

return [{ json: { rowCount: out.length, rows: out } }];

const source = $('Join & Filter Green Level').first().json;
const rows = source.rows || [];
if (!Array.isArray(rows) || rows.length === 0) throw new Error('No bundled rows for rm_green_level.');
return rows.map(row => ({ json: row }));
